pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up caller with enough Ether
        address alice = address(0x123);
        vm.deal(alice, 10 ether);

        // Warp to a known timestamp
        vm.warp(1000);

        // Alice calls Put with unlockTime far in the future
        vm.prank(alice);
        c.Put{value: 2 ether}(2000);

        // Now warp to a time after block.timestamp but before the chosen unlockTime (2000)
        vm.warp(1500);

        // Alice tries to Collect 1 ether (MinSum is 1 ether, balance is 2 ether)
        bool success;
        try c.Collect(1 ether) {
            success = true;
        } catch {
            success = false;
        }

        // Reference: Collect should revert because unlockTime (2000) > block.timestamp (1500)
        // Buggy: Collect should succeed because unlockTime was set to block.timestamp (1500)
        assertTrue(success, "Expected Collect to revert in reference, but it succeeded");
    }
}

