pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 2 ether);
        vm.warp(1);

        vm.prank(alice);
        c.Put{value: 1 ether}(1);

        vm.warp(2);

        vm.prank(alice);
        c.Collect(1 ether);

        uint256 bal = c.Acc(alice).balance;
        // reference: unlockTime = max(1,1)=1 -> block.timestamp(2)>1 => Collect succeeds => balance = 0
        // bug: unlockTime = _unlockTime (=1) -> also 1 => Collect succeeds => balance = 0
        // Wait, the difference is the opposite: in reference, if _unlockTime <= block.timestamp at Put time,
        // both assign block.timestamp (since max is block.timestamp). Let me refine: 

        // Actually, in the reference, unlockTime = _unlockTime>block.timestamp ? _unlockTime : block.timestamp.
        // With _unlockTime=1 and block.timestamp=1, unlockTime=1 (since 1>1 false). 
        // Bug: unlockTime = _unlockTime = 1. Both same! Need a different scenario.
        // Let me think: if _unlockTime > block.timestamp, reference sets _unlockTime, bug also sets _unlockTime same.
        // The only divergence: when _unlockTime <= block.timestamp, reference sets block.timestamp (later), bug sets _unlockTime (earlier).
        // So to make reference have later unlockTime than bug: set _unlockTime <= block.timestamp at Put.
        // Example: warped to block.timestamp=10, Put(_unlockTime=5). References sets unlockTime=10, bug sets 5.
        // Then after Collect at block.timestamp=6, bug Collect succeeds (6>5), reference fails (6<10).

        // Second try: better scenario
        vm.warp(10);
        vm.prank(alice);
        c.Put{value: 1 ether}(5);

        vm.warp(6);
        vm.prank(alice);
        c.Collect(1 ether);

        uint256 balAfter = c.Acc(alice).balance;
        // In reference: unlockTime=10, block.timestamp=6, Collect fails => balance remains 1 ether
        // In bug: unlockTime=5, block.timestamp=6, Collect succeeds => balance becomes 0
        assertTrue(balAfter == 1 ether, "Reference has balance 1 ether, bug has 0");
    }
}

