pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Deployer starts with enough ether
        vm.deal(address(this), 10 ether);

        // First deposit via Put (fallback): msg.value = 2 ether, unlockTime = 0
        // In reference: balance becomes 2 ether; in bug: balance becomes 2 - 2 = 0 (underflow? no, 0)
        // Actually bug: sub_uint256(0, 2) reverts because 0 < 2. So Put reverts.
        // To avoid that, we need initial balance > 0. Approach: first do a normal Put via explicit call?
        // But the contract's Put is payable and msg.sender must be caller.
        // Simpler: deployer sends ether directly to contract, then calls Put(block.timestamp + 1) with 0 value?
        // Better: first call Collect (which does nothing if balance insufficient) then Put via fallback.
        // We'll do: send 2 ether directly to c (via vm.deal? no, address(c).call{value: 2 ether}("") )
        // Then call Put(block.timestamp + 1) with 0 value to set unlockTime.
        // Then call Collect(1 ether) - should succeed in reference, fail in bug (due to balance decreased by Put? No, Put with 0 value does sub_uint256(acc.balance, 0) which is fine.
        // Actually mutant changes Put to subtract, so any positive msg.value will reduce balance.
        // Let's craft: first call Put with value 2 ether and unlockTime = 0 (so it unlocks immediately).
        // Reference: balance becomes 2. Bug: balance becomes sub_uint256(0, 2) = revert.
        // So test directly: vm.prank(caller); c.Put{value: 2 ether}(0); 
        // In bug, this reverts. So the test should try and catch.
        address caller = address(0x1234);
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        try c.Put{value: 2 ether}(0) {
            // succeeded in reference; now collect
            vm.warp(block.timestamp + 1);
            vm.prank(caller);
            try c.Collect(1 ether) {
                // collection succeeded
                assertTrue(true, "Reference works");
            } catch {
                assertTrue(false, "Reference should succeed");
            }
        } catch {
            // Bug: Put reverts, so we detect divergence
            assertTrue(false, "Buggy Put should revert");
        }
    }
}

